item.aggregated_output:
  1	import {createHash} from "node:crypto";
  2	
  3	import {aggregateDebtViews, calculateCovenantHeadroom, calculateImpliedEbitda, calculateLeverage} from "@offroad/financial-core";
  4	import Decimal from "decimal.js";
  5	import {z} from "zod";
  6	
  7	/**
  8	 * Executor of the method `reconcile-covenant-definitions` (v10, after the ninth independent review).
  9	 * It never writes "breached". Each indenture carries the anchor of its definitions and one anchor per
 10	 * tier; EBITDA adjustments are typed (denominator additions versus numerator obligations) and never
 11	 * folded together; the net debt of each instrument is computed from that instrument's own component
 12	 * list over dated component values with their own anchors, so a definition that adds leases or drops
 13	 * derivatives changes the number or refuses the comparison; the reported index is comparable only at
 14	 * the as-of date, with the same components and an opened EBITDA value; an ordinary settlement needs
 15	 * its date (so does an accelerated one); the next measurement follows the frequency the indenture
 16	 * states; every unproven tier leaves a written condition; a numerator obligation (sellers finance) is
 17	 * modeled with its own value or left as a legal condition, never folded into the EBITDA declaration;
 18	 * a legal condition on the numerator caps comparability; component lines, EBITDA and opening carry a
 19	 * unit and a twelve-month period. Net debt, leverage and headroom run through financial-core.
 20	 */
 21	const ratio = z.string().regex(/^\d+(\.\d+)?$/);
 22	const money = z.string().regex(/^-?\d+(\.\d+)?$/);
 23	const nonNegative = z.string().regex(/^\d+(\.\d+)?$/);
 24	const unitSchema = z.enum(["BRL", "BRL thousand", "BRL million", "USD", "USD thousand"]);
 25	const isoDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
 26	/** An indenture anchor cites a numbered clause (4.22.3(j), 7.24.3(VIII)); a label such as "índice financeiro" is not a clause. */
 27	const indentureAnchorSchema = z.object({document: z.string().min(1), clause: z.string().regex(/\d+(\.\d+)+/, "an indenture anchor needs a numbered clause"), page: z.number().int().positive()}).strict();
 28	const anchorSchema = z.object({document: z.string().min(1), clause: z.string().optional(), page: z.number().int().positive().optional(), note: z.string().optional()}).strict();
 29	type Anchor = z.infer<typeof anchorSchema>;
 30	
 31	/** The components a net debt definition is built from; comparability is decided on these, not on prose. */
 32	export const netDebtComponentSchema = z.enum([
 33	  "loans_and_financings", "debentures", "derivative_liabilities", "other_onerous_debt", "leases",
 34	  "cash_and_equivalents", "financial_investments", "derivative_assets",
 35	]);
 36	type NetDebtComponent = z.infer<typeof netDebtComponentSchema>;
 37	const DEDUCTIONS = new Set<NetDebtComponent>(["cash_and_equivalents", "financial_investments", "derivative_assets"]);
 38	/** The words a clause uses for each component; a structured component the text never names is a tag, not a definition. */
 39	const COMPONENT_WORDS: Record<NetDebtComponent, RegExp> = {
 40	  loans_and_financings: /emprestim|financiament|loan|borrowing|divida bruta|gross debt/,
 41	  debentures: /debenture|divida bruta|gross debt/,
 42	  derivative_liabilities: /derivativ|derivative/,
 43	  other_onerous_debt: /outra|other|onerosa|onerous/,
 44	  leases: /arrendament|lease/,
 45	  cash_and_equivalents: /caixa|disponibilidade|cash/,
 46	  financial_investments: /aplicac|investment/,
 47	  derivative_assets: /derivativ|derivative/,
 48	};
 49	/** An open-ended residual ("qualquer outra dívida onerosa"): its absence from the base is a condition, not a mismatch. */
 50	const RESIDUAL: NetDebtComponent = "other_onerous_debt";
 51	
 52	export const covenantTierSchema = z.object({
 53	  limit: ratio,
 54	  condition: z.discriminatedUnion("type", [
 55	    z.object({type: z.literal("unconditional")}).strict(),
 56	    z.object({type: z.literal("until_reference_settled"), referenceInstruments: z.array(z.string().min(1)).min(1)}).strict(),
 57	    z.object({type: z.literal("after_reference_settled"), referenceInstruments: z.array(z.string().min(1)).min(1)}).strict(),
 58	  ]),
 59	  anchor: indentureAnchorSchema,
 60	}).strict();
 61	
 62	/** Adjustments beyond the base EBITDA definition, typed by the side of the ratio they touch. */
 63	export const ebitdaAdjustmentSchema = z.object({
 64	  id: z.string().min(1),
 65	  kind: z.enum(["denominator_addition", "numerator_obligation", "other"]),
 66	  description: z.string().min(1),
 67	  anchor: indentureAnchorSchema,
 68	  /** For a numerator obligation: its dated value in the base, or null when the base does not state it. */
 69	  obligation: z.object({value: nonNegative, asOf: isoDate, anchor: anchorSchema}).strict().nullable().default(null),
 70	}).strict();
 71	
 72	export const covenantInstrumentSchema = z.discriminatedUnion("source", [
 73	  z.object({
 74	    source: z.literal("indenture"),
 75	    id: z.string().min(1),
 76	    indexName: z.string().min(1),
 77	    direction: z.enum(["maximum", "minimum"]).default("maximum"),
 78	    netDebtDefinition: z.string().min(1),
 79	    /** The perimeter the definition measures; the reported index must match it to be comparable. */
 80	    perimeter: z.enum(["consolidated", "parent"]).default("consolidated"),
 81	    netDebtComponents: z.array(netDebtComponentSchema).min(1),
 82	    ebitdaDefinition: z.string().min(1),
 83	    ebitdaAdjustments: z.array(ebitdaAdjustmentSchema).default([]),
 84	    measurement: z.object({frequency: z.enum(["annual", "semiannual", "quarterly"]), basis: z.string().min(1), fiscalYearEnd: z.string().regex(/^\d{2}-\d{2}$/)}).strict(),
 85	    /** Tiers in the order the indenture states them. */
 86	    tiers: z.array(covenantTierSchema).min(1),
 87	    /** One anchor per definition: the net debt clause and the EBITDA clause sit on different pages. */
 88	    definitionAnchors: z.object({netDebt: indentureAnchorSchema, ebitda: indentureAnchorSchema}).strict(),
 89	  }).strict(),
 90	  z.object({
 91	    source: z.literal("trustee_report"),
 92	    id: z.string().min(1),
 93	    indexName: z.string().min(1),
 94	    reportedLimit: ratio,
 95	    reportedMeasurement: z.object({value: ratio, asOf: isoDate}).strict().nullable().default(null),
 96	    anchor: anchorSchema,
 97	  }).strict(),
 98	]);
 99	
100	/** One line of the base with the components it covers (an aggregated note line may cover two), its date and its own anchor. */
101	export const componentValueSchema = z.object({
102	  component: netDebtComponentSchema,
103	  covers: z.array(netDebtComponentSchema).min(1),
104	  value: nonNegative,
105	  unit: unitSchema,
106	  perimeter: z.enum(["consolidated", "parent"]).default("consolidated"),
107	  asOf: isoDate,
108	  anchor: anchorSchema,
109	}).strict();
110	
111	export const covenantReconciliationInputSchema = z.object({
112	  asOfDate: isoDate,
113	  /** The unit of every monetary value in the base; lines, EBITDA and openings must state the same. */
114	  unit: unitSchema,
115	  instruments: z.array(covenantInstrumentSchema),
116	  referenceSettlements: z.array(z.object({
117	    instrument: z.string().min(1),
118	    maturityDate: isoDate,
119	    /** ordinary: settled in the ordinary course (needs the date); accelerated: settled by acceleration; outstanding: still alive; unknown: the base does not say. */
120	    settlement: z.enum(["ordinary", "accelerated", "outstanding", "unknown"]),
121	    settlementDate: isoDate.nullable().default(null),
122	    anchor: anchorSchema,
123	  }).strict()).default([]),
124	  componentValues: z.array(componentValueSchema).default([]),
125	  /** Dated lines of the base that may belong to a numerator obligation (acquisition payables, contingent consideration) but are not yet classified; they are carried as uncovered terms, never added and never called absent. */
126	  candidateObligations: z.array(z.object({id: z.string().min(1), description: z.string().min(1), value: nonNegative, unit: unitSchema, asOf: isoDate, relatedAdjustmentId: z.string().min(1).nullable().default(null), anchor: anchorSchema}).strict()).default([]),
127	  /** LTM EBITDA as the company computes it for the covenant, when it is opened, with the adjustment ids it already incorporates. */
128	  ltmEbitda: z.object({value: money, unit: unitSchema, perimeter: z.enum(["consolidated", "parent"]).default("consolidated"), asOf: isoDate, months: z.literal(12), incorporatesAdjustments: z.array(z.string().min(1)).default([]), anchor: anchorSchema}).strict().nullable().default(null),
129	  reported: z.object({
130	    value: ratio,
131	    asOf: isoDate,
132	    definition: z.string().min(1),
133	    /** The components the base actually enumerates for the reported net debt, not the contractual phrase. */
134	    netDebtComponents: z.array(netDebtComponentSchema).min(1),
135	    perimeter: z.enum(["consolidated", "parent"]).default("consolidated"),
136	    /** The opened EBITDA behind the reported index, when the base shows it; a flag is not an opening. */
137	    ebitdaOpening: z.object({value: money, unit: unitSchema, asOf: isoDate, months: z.literal(12), anchor: anchorSchema}).strict().nullable().default(null),
138	    anchor: anchorSchema,
139	  }).strict().nullable().default(null),
140	}).strict().superRefine((input, context) => {
141	  const seenFacts = new Set<string>();
142	  input.referenceSettlements.forEach((fact, index) => {
143	    if (seenFacts.has(fact.instrument)) context.addIssue({code: "custom", path: ["referenceSettlements", index], message: `duplicate settlement fact for ${fact.instrument}`});
144	    seenFacts.add(fact.instrument);
145	    if ((fact.settlement === "ordinary" || fact.settlement === "accelerated") && fact.settlementDate === null) context.addIssue({code: "custom", path: ["referenceSettlements", index, "settlementDate"], message: `a settlement of ${fact.instrument} (${fact.settlement}) needs its date; without it the fact is unknown`});
146	  });
147	  const seenInstruments = new Set<string>();
148	  input.instruments.forEach((instrument, index) => {
149	    if (seenInstruments.has(instrument.id)) context.addIssue({code: "custom", path: ["instruments", index], message: `duplicate instrument ${instrument.id}`});
150	    seenInstruments.add(instrument.id);
151	    if (instrument.source === "indenture") {
152	      const text = instrument.netDebtDefinition.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();
153	      for (const component of instrument.netDebtComponents) {
154	        if (!COMPONENT_WORDS[component].test(text)) context.addIssue({code: "custom", path: ["instruments", index, "netDebtComponents"], message: `${instrument.id}: the definition text never names the component ${component}; the structured components must be readable in the clause`});
155	      }
156	      const adjustmentIds = new Set<string>();
157	      instrument.ebitdaAdjustments.forEach((adjustment, position) => {
158	        if (adjustmentIds.has(adjustment.id)) context.addIssue({code: "custom", path: ["instruments", index, "ebitdaAdjustments", position], message: `duplicate adjustment ${adjustment.id}`});
159	        adjustmentIds.add(adjustment.id);
160	      });
161	    }
162	  });
163	  const covered = new Set<string>();
164	  input.componentValues.forEach((line, index) => {
165	    if (!line.covers.includes(line.component)) context.addIssue({code: "custom", path: ["componentValues", index, "covers"], message: "a line must cover its own component"});
166	    const sides = new Set(line.covers.map((component) => (DEDUCTIONS.has(component) ? "deduction" : "debt")));
167	    if (sides.size > 1) context.addIssue({code: "custom", path: ["componentValues", index, "covers"], message: `line ${line.component} aggregates debt and deductions; the base must decompose it before it enters a net debt`});
168	    if (line.asOf !== input.asOfDate) context.addIssue({code: "custom", path: ["componentValues", index, "asOf"], message: `component ${line.component} is dated ${line.asOf}, not the as-of date ${input.asOfDate}`});
169	    for (const component of line.covers) {
170	      if (covered.has(component)) context.addIssue({code: "custom", path: ["componentValues", index], message: `component ${component} is covered twice`});
171	      covered.add(component);
172	    }
173	  });
174	  if (input.ltmEbitda && input.ltmEbitda.asOf !== input.asOfDate) context.addIssue({code: "custom", path: ["ltmEbitda", "asOf"], message: "the opened EBITDA must be dated at the as-of date"});
175	  if (input.reported?.ebitdaOpening && input.reported.ebitdaOpening.asOf !== input.asOfDate) context.addIssue({code: "custom", path: ["reported", "ebitdaOpening", "asOf"], message: "the EBITDA opening behind the reported index must be dated at the as-of date"});
176	  const units = new Set<string>([input.unit, ...input.componentValues.map((line) => line.unit), ...(input.ltmEbitda ? [input.ltmEbitda.unit] : []), ...(input.reported?.ebitdaOpening ? [input.reported.ebitdaOpening.unit] : [])]);
177	  if (units.size > 1) context.addIssue({code: "custom", path: ["componentValues"], message: `one unit per base: ${[...units].sort().join(", ")} were given`});
178	  input.instruments.forEach((instrument, index) => {
179	    if (instrument.source !== "indenture") return;
180	    instrument.ebitdaAdjustments.forEach((adjustment, position) => {
181	      if (adjustment.obligation && adjustment.kind !== "numerator_obligation") context.addIssue({code: "custom", path: ["instruments", index, "ebitdaAdjustments", position, "obligation"], message: "only a numerator obligation carries an obligation value"});
182	      if (adjustment.obligation && adjustment.obligation.asOf !== input.asOfDate) context.addIssue({code: "custom", path: ["instruments", index, "ebitdaAdjustments", position, "obligation", "asOf"], message: "an obligation value must be dated at the as-of date"});
183	    });
184	  });
185	  if (input.reported && input.reported.asOf > input.asOfDate) context.addIssue({code: "custom", path: ["reported", "asOf"], message: "the reported index is dated after the as-of date"});
186	});
187	export type CovenantReconciliationInput = z.input<typeof covenantReconciliationInputSchema>;
188	
189	type Comparability = "comparable" | "conditional" | "not_comparable" | "no_index";
190	type Calculation = {id: string; formula: string; operands: Record<string, string>; result: string; unit: string};
191	
192	export type CovenantReconciliationOutput = {
193	  schema_version: "method.reconcile-covenant-definitions.v10";
194	  as_of_date: string;
195	  /** The unit every value below is expressed in; part of the output and of its fingerprint. */
196	  unit: string;
197	  state: "resolved" | "conditioned" | "blocked";
198	  block_reasons: string[];
199	  covenants: Array<{
200	    instrument: string;
201	    source: "indenture" | "trustee_report";
202	    indexName: string;
203	    direction: "maximum" | "minimum" | null;
204	    definitions: {netDebt: string; netDebtComponents: string[]; ebitda: string; ebitdaAdjustments: Array<{id: string; kind: string; description: string; anchor: Anchor; obligation: {value: string; asOf: string; anchor: Anchor} | null}>; anchors: {netDebt: Anchor; ebitda: Anchor}} | null;
205	    measurement: {frequency: string; basis: string; fiscalYearEnd: string; nextMeasurementDate: string} | null;
206	    tiers: Array<{index: number; limit: string; condition: string; state: "applies" | "ended" | "not_yet" | "unproven" | "n/a"; anchor: Anchor}>;
207	    applicableLimit: string | null;
208	    limitState: "resolved" | "reported_by_trustee" | "insufficient_evidence";
209	    limitConditions: string[];
210	    reportedMeasurement: {value: string; asOf: string} | null;
211	    netDebtByDefinition: {value: string; formula: string; operands: Record<string, string>; anchors: Record<string, Anchor>; residualAssumedZero: boolean; numeratorObligations: string | null} | null;
212	    legalConditions: string[];
213	    index: {value: string; basis: "computed_from_components" | "reported"; ebitda: {value: string; basis: "opened" | "implied_from_reported"} | null; anchor: Anchor} | null;
214	    /** Facts that explain the tier resolution without being conditions: a proven acceleration, for instance. */
215	    notes: string[];
216	    comparability: Comparability;
217	    comparabilityReasons: string[];
218	    headroom: {absolute: string; relative: string | null; basis: string} | null;
219	    status: "within_limit" | "above_limit_interim" | "unresolved";
220	  }>;
221	  unproven_conditions: string[];
222	  /** Candidate lines and numerator obligations without a classified value, as insufficient_evidence, never added and never called absent. */
223	  uncovered_terms: Array<{id: string; state: "insufficient_evidence"; reason: string}>;
224	  legal_conditions: string[];
225	  trace: {calculations: Calculation[]; inputFingerprint: string; outputFingerprint: string};
226	};
227	
228	const d = (value: Decimal.Value) => new Decimal(value);
229	const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
230	const stableStringify = (value: unknown): string => JSON.stringify(value, (_key, inner: unknown) => (inner && typeof inner === "object" && !Array.isArray(inner) ? Object.fromEntries(Object.entries(inner as Record<string, unknown>).sort(([a], [b]) => compare(a, b))) : inner));
231	const fingerprint = (value: unknown) => createHash("sha256").update(stableStringify(value)).digest("hex");
232	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
233	const sortStrings = (values: readonly string[]) => [...values].sort(compare);
234	
235	const lastDay = (year: number, month: number) => new Date(Date.UTC(year, month, 0)).getUTCDate();
236	/** Next measurement after the as-of date: the fiscal year end and, for shorter frequencies, the month ends between. */
237	export function nextMeasurement(asOf: string, fiscalYearEnd: string, frequency: "annual" | "semiannual" | "quarterly"): string {
238	  const [endMonth, endDay] = fiscalYearEnd.split("-").map(Number) as [number, number];
239	  const step = frequency === "annual" ? 12 : frequency === "semiannual" ? 6 : 3;
240	  const year = Number(asOf.slice(0, 4));
241	  const candidates: string[] = [];
242	  for (const base of [year - 1, year, year + 1]) {
243	    for (let offset = 0; offset < 12; offset += step) {
244	      const total = endMonth - 1 + offset;
245	      const y = base + Math.floor(total / 12);
246	      const m = (total % 12) + 1;
247	      const day = endDay >= lastDay(2026, endMonth) ? lastDay(y, m) : Math.min(endDay, lastDay(y, m)); // a day at the month's end means the month's end, leap years included
248	      candidates.push(`${y}-${String(m).padStart(2, "0")}-${String(day).padStart(2, "0")}`);
249	    }
250	  }
251	  return candidates.filter((candidate) => candidate > asOf).sort(compare)[0]!;
252	}
253	
254	function canonical(input: z.infer<typeof covenantReconciliationInputSchema>) {
255	  return {
256	    ...input,
257	    candidateObligations: [...input.candidateObligations].sort((a, b) => compare(a.id, b.id)),
258	    instruments: [...input.instruments].sort((a, b) => compare(a.id, b.id)).map((instrument) => instrument.source === "indenture"
259	      ? {
260	          ...instrument,
261	          netDebtComponents: sortStrings(instrument.netDebtComponents) as NetDebtComponent[],
262	          ebitdaAdjustments: [...instrument.ebitdaAdjustments].sort((a, b) => compare(a.id, b.id)),
263	          tiers: instrument.tiers.map((tier) => tier.condition.type === "unconditional" ? tier : {...tier, condition: {...tier.condition, referenceInstruments: sortStrings(tier.condition.referenceInstruments)}}),
264	        }
265	      : instrument),
266	    referenceSettlements: [...input.referenceSettlements].sort((a, b) => compare(a.instrument, b.instrument)),
267	    componentValues: [...input.componentValues].sort((a, b) => compare(a.component, b.component)).map((line) => ({...line, covers: sortStrings(line.covers) as NetDebtComponent[]})),
268	    ltmEbitda: input.ltmEbitda ? {...input.ltmEbitda, incorporatesAdjustments: sortStrings(input.ltmEbitda.incorporatesAdjustments)} : null,
269	    reported: input.reported ? {...input.reported, netDebtComponents: sortStrings(input.reported.netDebtComponents) as NetDebtComponent[]} : null,
270	  };
271	}
272	
273	export function reconcileCovenantDefinitions(raw: CovenantReconciliationInput): CovenantReconciliationOutput {
274	  const input = canonical(covenantReconciliationInputSchema.parse(raw));
275	  const unit = input.unit;
276	  const calculations: Calculation[] = [];
277	  /** Monetary calculations carry the base unit; leverage and headroom are ratios, written as "x". */
278	  const record = (calculation: Omit<Calculation, "unit">) => calculations.push({...calculation, unit: /net_leverage|covenant_headroom/.test(calculation.id) ? "x" : unit});
279	  const blockReasons: string[] = [];
280	  if (input.instruments.length === 0) blockReasons.push("no indenture and no trustee report in the base: nothing to reconcile");
281	
282	  const lineFor = new Map<NetDebtComponent, (typeof input.componentValues)[number]>();
283	  for (const line of input.componentValues) for (const component of line.covers) lineFor.set(component, line);
284	  const settlements = new Map(input.referenceSettlements.map((fact) => [fact.instrument, fact]));
285	  const unproven = new Set<string>();
286	  const legal = new Set<string>();
287	  const leasesLine = lineFor.get("leases");
288	
289	  const covenants = input.instruments.map((instrument): CovenantReconciliationOutput["covenants"][number] => {
290	    if (instrument.source === "trustee_report") {
291	      return {
292	        instrument: instrument.id, source: "trustee_report", indexName: instrument.indexName, direction: null, definitions: null, measurement: null,
293	        tiers: [{index: 0, limit: instrument.reportedLimit, condition: "as reported by the trustee; the indenture is not in the base", state: "n/a", anchor: instrument.anchor}], notes: [],
294	        applicableLimit: instrument.reportedLimit, limitState: "reported_by_trustee",
295	        limitConditions: ["the indenture is not in the base: the limit is the trustee's report and no headroom is asserted"],
296	        reportedMeasurement: instrument.reportedMeasurement,
297	        netDebtByDefinition: null, legalConditions: [], index: null,
298	        comparability: "not_comparable", comparabilityReasons: ["definition, perimeter, adjustments and measurement date are not readable without the indenture"],
299	        headroom: null, status: "unresolved",
300	      };
301	    }
302	
303	    // 1. Which tier applies, from dated facts only.
304	    const conditions: string[] = [];
305	    const notes: string[] = [];
306	    const tiers: CovenantReconciliationOutput["covenants"][number]["tiers"] = [];
307	    let applicable: {limit: string; tier: number} | null = null;
308	    instrument.tiers.forEach((tier, index) => {
309	      const condition = tier.condition;
310	      if (condition.type === "unconditional") {
311	        tiers.push({index, limit: tier.limit, condition: "unconditional", state: applicable ? "n/a" : "applies", anchor: tier.anchor});
312	        applicable ??= {limit: tier.limit, tier: index};
313	        return;
314	      }
315	      const facts = condition.referenceInstruments.map((reference) => settlements.get(reference) ?? null);
316	      // A reference instrument is over when it matured or was settled ordinarily on a proven date; an accelerated
317	      // settlement keeps the lower tier; a maturity passed without proof of settlement is unproven.
318	      const over = facts.map((fact) => {
319	        if (!fact) return "unknown" as const;
320	        const settledOn = fact.settlementDate !== null && fact.settlementDate <= input.asOfDate;
321	        if (fact.settlement === "ordinary" && settledOn) return "ordinary" as const;
322	        if (fact.settlement === "accelerated" && settledOn) return "accelerated" as const;
323	        if (fact.maturityDate <= input.asOfDate) return fact.settlement === "outstanding" ? "outstanding_after_maturity" as const : "matured_unproven" as const;
324	        return "alive" as const; // a settlement dated after the as-of date is not a fact yet
325	      });
326	      const label = condition.referenceInstruments.join(", ");
327	      if (condition.type === "until_reference_settled") {
328	        // "Whichever comes first" across the references: the tier ends at the first maturity or dated ordinary settlement.
329	        if (over.some((state) => state === "unknown")) {
330	          tiers.push({index, limit: tier.limit, condition: `until the first of ${label} matures or is settled ordinarily`, state: "unproven", anchor: tier.anchor});
331	          conditions.push(`the end of the ${tier.limit}x tier requires the maturity or settlement facts of every reference (${label}); the base lacks them for ${condition.referenceInstruments.filter((_reference, position) => over[position] === "unknown").join(", ")}${over.some((state) => state === "accelerated") ? "; an accelerated settlement of another reference does not settle the question" : ""}`);
332	          return;
333	        }
334	        if (over.some((state) => state === "accelerated") && !over.some((state) => state === "ordinary" || state === "matured_unproven" || state === "outstanding_after_maturity")) {
